from decimal import Decimal
from typing import Any


def _value(source: dict | None, key: str) -> Any:
    if not source:
        return ""
    value = source.get(key, "")
    return "" if value is None else value


def _nvl(value: Any, default: Any) -> Any:
    return default if value in ("", None) else value


def _number(value: Any) -> Decimal:
    value = _nvl(value, 0)
    if isinstance(value, Decimal):
        return value
    return Decimal(str(value))


def _date(value: Any) -> str:
    value = _nvl(value, "")
    return str(value)


def _date_eq(left: Any, right: Any) -> bool:
    left_s = _date(left)
    right_s = _date(right)
    if left_s == "00000000" or right_s == "00000000":
        return left_s == "00000000" and right_s == "00000000"
    return left_s == right_s


def _date_ge(left: Any, right: Any) -> bool:
    left_s = _date(left)
    right_s = _date(right)
    if left_s == "00000000" or right_s == "00000000":
        return False
    return left_s >= right_s


def _failure(code: str, message: str, severity: str = "BLOCK") -> dict:
    return {
        "code": code,
        "message": message,
        "severity": severity,
    }


def validate(
    record: dict,
    old: dict | None = None,
    event: str = "INSERT",
    today: str = "20260901",
) -> list[dict]:
    errors: list[dict] = []

    stat_cd = _value(record, "STAT_CD")
    amount = _value(record, "AMT")
    lost_rsn = _value(record, "LOST_RSN")
    close_dt = _value(record, "CLOSE_DT")
    stage_pct = _value(record, "STAGE_PCT")

    # OPP-001
    if event in ("INSERT", "UPDATE"):
        if not (_number(_nvl(amount, 0)) >= Decimal("0")):
            errors.append(_failure("E3001", "Amount negative"))

    # OPP-002
    if event in ("INSERT", "UPDATE"):
        if not (not (stat_cd == "W" and _number(_nvl(amount, 0)) == Decimal("0"))):
            errors.append(_failure("E3002", "Won opportunity requires amount"))

    # OPP-003
    if event in ("INSERT", "UPDATE"):
        if not (not (stat_cd == "L" and lost_rsn == "")):
            errors.append(_failure("E3003", "Lost reason required"))

    # OPP-004
    if event in ("INSERT", "UPDATE"):
        if not (not (stat_cd == "W" and _date_eq(close_dt, "00000000"))):
            errors.append(_failure("E3004", "Won opportunity requires close date"))

    # OPP-005
    if event == "UPDATE":
        old_stat_cd = _value(old, "STAT_CD")
        if not (not (old_stat_cd == "W" and stat_cd != "W")):
            errors.append(_failure("E3005", "Cannot reopen a won opportunity"))

    # OPP-006
    if event in ("INSERT", "UPDATE"):
        stage = _number(_nvl(stage_pct, 0))
        consistent = (
            (stat_cd == "P" and stage == Decimal("10"))
            or (stat_cd == "Q" and stage == Decimal("25"))
            or (stat_cd == "N" and stage == Decimal("60"))
            or (stat_cd == "W" and stage == Decimal("100"))
            or (stat_cd == "L" and stage == Decimal("0"))
        )
        if not consistent:
            errors.append(_failure("E3006", "Stage percent inconsistent with status"))

    # OPP-007
    if event == "INSERT":
        if not (_date_eq(close_dt, "00000000") or _date_ge(close_dt, today)):
            errors.append(_failure("E3007", "Close date in past", "WARN"))

    return errors


def is_blocked(errors: list[dict]) -> bool:
    return any(error.get("severity") == "BLOCK" for error in errors)
